//! `xtask chromium expectations check` (ADR 0074): the expected results under
//! `chromium/expectations/` cannot hide a patch regression as upstream.
//!
//! The set, in each runner's own format:
//! - `gtest/<suite>-<platform>.filter`: `--test-launcher-filter-file` files,
//!   one `-Suite.Test` line per entry. A comment line `# <category>
//!   <key>=<value>...` gives the entries below it, up to the next blank line
//!   or category line, their category and evidence.
//! - `gtest/generated/<suite>-<platform>.filter`: the generated
//!   `upstream-flaky` entries, under a `# Generated by: <command>` line and a
//!   `# Tracking issue: #<n>` line.
//! - `wpt/control/` and `wpt/goodfetch/`: the wptrunner metadata trees of the
//!   Control build and of the Goodfetch Chromium. A section with an
//!   `expected` key is an entry, and its `category` key gives its category
//!   and evidence in the same `<category> <key>=<value>...` form.
//!
//! The evidence each category needs: `upstream`, a `link=https://…` or the
//! ungoogled `setting=…` that causes it; `upstream-flaky`, a `rate=…%` when
//! generated, otherwise its `issue=#<n>`, the `upstream=https://…` report,
//! the diagnostic `run=https://…` showing both outcomes and the `date=` of
//! its last renewal; `intended`, its `patch=` and its `surface=` row.
//!
//! A test is named as the run's JUnit files name it, its class name then its
//! name: `<suite> <Suite.Test>` for a gtest, `wpt <url>` for a WPT test and
//! `wpt <url> > <subtest>` for a subtest.
#![expect(
    clippy::disallowed_methods,
    reason = "xtask is synchronous; the blocking-fs ban targets async crates (STYLE.md)"
)]

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use anyhow::{Context as _, Result, bail};
use jiff::civil::Date;

use crate::check::{self, Finding};
use crate::environment::Environment;
use crate::junit::{self, Ending};

/// The expectations, from the repository root.
const FOLDER: &str = "chromium/expectations";

/// A recheck of this many passes and no failure makes an entry stale.
const RECHECK_RUNS: u32 = 20;

/// The days an `upstream-flaky` entry lasts after its last renewal: 8 weeks.
const LIFETIME_DAYS: i64 = 56;

#[derive(clap::Subcommand)]
pub(crate) enum Command {
    /// Fails on an entry without its category or evidence, WPT metadata trees
    /// that differ outside `intended` entries, a widened Goodfetch Chromium
    /// expectation and an expired `upstream-flaky` entry; given a run's JUnit
    /// results, on an `upstream` entry or exclusion that passed on the
    /// Control build, an expected failure that passed and an entry the
    /// recheck found stale.
    Check {
        /// The platform the results are of: `linux`, `mac` or `windows`.
        #[arg(long)]
        platform: Option<String>,
        /// The Control build's JUnit files.
        #[arg(long, requires = "platform")]
        control: Option<PathBuf>,
        /// The Goodfetch Chromium's JUnit files.
        #[arg(long, requires = "platform")]
        goodfetch: Option<PathBuf>,
        /// The JUnit files of the recheck's 20 runs on the Control build.
        #[arg(long, requires = "platform")]
        recheck: Option<PathBuf>,
        /// Today's date in UTC, `YYYY-MM-DD`; the system's when left out.
        #[arg(long)]
        today: Option<Date>,
    },
    /// Rewrites each suite's generated `upstream-flaky` files from LUCI
    /// Analysis's record of Chromium's CI, one per platform with entries,
    /// each under the command that made it and its tracking issue, opened
    /// when the file has none; removes the suite's files left without
    /// entries.
    Regenerate(super::regenerate::Arguments),
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Category {
    Upstream,
    UpstreamFlaky,
    Intended,
}

/// Where an entry is.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Source {
    /// A hand-written filter file.
    Filter,
    /// A generated filter file.
    Generated,
    ControlTree,
    GoodfetchTree,
}

struct Entry {
    test: String,
    /// Its file, from the expectations' folder.
    file: String,
    source: Source,
    /// A filter file's platform.
    platform: Option<String>,
    category: Option<(Category, BTreeMap<String, String>)>,
    /// A metadata entry's `expected` value.
    expected: Option<String>,
}

pub(crate) fn run(command: &Command, environment: &Environment) -> Result<ExitCode> {
    match command {
        Command::Check {
            platform,
            control,
            goodfetch,
            recheck,
            today,
        } => check(
            platform.as_deref(),
            [control, goodfetch, recheck].map(Option::as_deref),
            *today,
            environment,
        ),
        Command::Regenerate(arguments) => super::regenerate::run(arguments, environment),
    }
}

/// The checks, given the results of the Control build, the Goodfetch
/// Chromium and the recheck, in that order, when there are some.
fn check(
    platform: Option<&str>,
    [control, goodfetch, recheck]: [Option<&Path>; 3],
    today: Option<Date>,
    environment: &Environment,
) -> Result<ExitCode> {
    let today = today.unwrap_or_else(|| {
        jiff::Timestamp::now()
            .to_zoned(jiff::tz::TimeZone::UTC)
            .date()
    });
    let folder = environment.root.join(FOLDER);
    let mut findings = Vec::new();
    let entries = read(&folder, &mut findings)?;
    for entry in &entries {
        categorized(entry, &mut findings);
        expired(entry, today, &mut findings)?;
    }
    trees(&entries, &mut findings);
    let applies =
        |entry: &&Entry| entry.platform.is_none() || entry.platform.as_deref() == platform;
    if let Some(control) = control {
        let results = results(&environment.path(control))?;
        for entry in entries.iter().filter(applies) {
            control_passed(entry, &results, &mut findings);
        }
    }
    if let Some(goodfetch) = goodfetch {
        let results = results(&environment.path(goodfetch))?;
        for entry in entries
            .iter()
            .filter(|entry| entry.source == Source::GoodfetchTree)
        {
            if failure_expected(entry) && passed(&results, &entry.test) {
                findings.push(Finding::new(
                    "expected-failure-passed",
                    &entry.test,
                    format!(
                        "`{}` expects a failure, but it passed on the Goodfetch Chromium",
                        entry.file
                    ),
                ));
            }
        }
    }
    if let Some(recheck) = recheck {
        let results = results(&environment.path(recheck))?;
        for entry in entries.iter().filter(applies) {
            stale(entry, &results, &mut findings);
        }
    }
    Ok(check::report(&findings))
}

/// Every entry of the set; a generated file without its command or its
/// tracking issue, and a filter file not named `<suite>-<platform>.filter`,
/// are findings.
fn read(folder: &Path, findings: &mut Vec<Finding>) -> Result<Vec<Entry>> {
    let mut entries = Vec::new();
    for (file, generated) in [("gtest", false), ("gtest/generated", true)] {
        for path in files(&folder.join(file), "filter", false)? {
            let relative = relative(folder, &path)?;
            let text = std::fs::read_to_string(&path)
                .with_context(|| format!("reading {}", path.display()))?;
            if generated && !(has_command(&text) && has_issue(&text)) {
                findings.push(Finding::new(
                    "no-evidence",
                    &relative,
                    "a generated file starts with `# Generated by: <command>` and `# Tracking issue: #<n>`",
                ));
            }
            let Some((suite, platform)) = path
                .file_stem()
                .and_then(|stem| stem.to_str())
                .and_then(|stem| stem.rsplit_once('-'))
            else {
                findings.push(Finding::new(
                    "misnamed",
                    &relative,
                    "a filter file is named `<suite>-<platform>.filter`",
                ));
                continue;
            };
            let source = if generated {
                Source::Generated
            } else {
                Source::Filter
            };
            filter(&text, suite, platform, &relative, source, &mut entries);
        }
    }
    for (tree, source) in [
        ("wpt/control", Source::ControlTree),
        ("wpt/goodfetch", Source::GoodfetchTree),
    ] {
        let root = folder.join(tree);
        for path in files(&root, "ini", true)? {
            let text = std::fs::read_to_string(&path)
                .with_context(|| format!("reading {}", path.display()))?;
            let directory = relative(&root, path.parent().unwrap_or(&root))?;
            metadata(
                &text,
                &directory,
                &relative(folder, &path)?,
                source,
                &mut entries,
            )
            .with_context(|| format!("reading {}", path.display()))?;
        }
    }
    Ok(entries)
}

/// The files ending in `.<extension>` in `folder`, under it when `deep`, in
/// order; none when it is absent.
fn files(folder: &Path, extension: &str, deep: bool) -> Result<Vec<PathBuf>> {
    let mut found = Vec::new();
    if !folder.is_dir() {
        return Ok(found);
    }
    for entry in
        std::fs::read_dir(folder).with_context(|| format!("reading {}", folder.display()))?
    {
        let path = entry?.path();
        if path.is_dir() {
            if deep {
                found.extend(files(&path, extension, deep)?);
            }
        } else if path.extension().is_some_and(|found| found == extension) {
            found.push(path);
        }
    }
    found.sort();
    Ok(found)
}

fn relative(base: &Path, path: &Path) -> Result<String> {
    let relative = path.strip_prefix(base)?;
    let text = relative
        .to_str()
        .with_context(|| format!("{} is not named in UTF-8", path.display()))?;
    Ok(text.replace('\\', "/"))
}

fn has_command(text: &str) -> bool {
    text.lines().any(|line| {
        line.strip_prefix("# Generated by: ")
            .is_some_and(|command| !command.trim().is_empty())
    })
}

fn has_issue(text: &str) -> bool {
    text.lines().any(|line| {
        line.strip_prefix("# Tracking issue: ")
            .is_some_and(|issue| is_issue(issue.trim()))
    })
}

fn is_issue(text: &str) -> bool {
    text.strip_prefix('#').is_some_and(|number| {
        !number.is_empty() && number.bytes().all(|byte| byte.is_ascii_digit())
    })
}

/// A filter file's entries: each line but comments and blank lines, under
/// the category line above it, if any, up to a blank line.
fn filter(
    text: &str,
    suite: &str,
    platform: &str,
    file: &str,
    source: Source,
    entries: &mut Vec<Entry>,
) {
    let mut category = None;
    for line in text.lines().map(str::trim) {
        if line.is_empty() {
            category = None;
        } else if let Some(comment) = line.strip_prefix('#') {
            if let Some(parsed) = categorized_as(comment) {
                category = Some(parsed);
            }
        } else {
            let name = line.strip_prefix('-').unwrap_or(line);
            entries.push(Entry {
                test: format!("{suite} {name}"),
                file: file.to_owned(),
                source,
                platform: Some(platform.to_owned()),
                category: category.clone(),
                expected: None,
            });
        }
    }
}

/// A `<category> <key>=<value>...` text's category and evidence; none when
/// it starts with no category.
fn categorized_as(text: &str) -> Option<(Category, BTreeMap<String, String>)> {
    let mut words = text.split_whitespace();
    let category = match words.next()? {
        "upstream" => Category::Upstream,
        "upstream-flaky" => Category::UpstreamFlaky,
        "intended" => Category::Intended,
        _ => return None,
    };
    let evidence = words
        .map(|word| {
            let (key, value) = word.split_once('=').unwrap_or((word, ""));
            (key.to_owned(), value.to_owned())
        })
        .collect();
    Some((category, evidence))
}

/// A wptrunner metadata file's entries: its sections with an `expected`
/// key, nested by indentation, the first naming the test in `directory`.
fn metadata(
    text: &str,
    directory: &str,
    file: &str,
    source: Source,
    entries: &mut Vec<Entry>,
) -> Result<()> {
    // Each open section's indentation and its index in `sections`.
    let mut open: Vec<(usize, usize)> = Vec::new();
    let mut sections: Vec<(Vec<String>, BTreeMap<String, String>)> = Vec::new();
    // The key a more indented line continues: its section and indentation.
    let mut continued: Option<(usize, String, usize)> = None;
    for line in text.lines() {
        let content = line.trim();
        if content.is_empty() || content.starts_with('#') {
            continue;
        }
        let indent = line.len() - line.trim_start().len();
        if let Some((section, key, key_indent)) = &continued
            && indent > *key_indent
        {
            let value = sections[*section].1.entry(key.clone()).or_default();
            value.push('\n');
            value.push_str(content);
            continue;
        }
        continued = None;
        open.retain(|(open_indent, _)| *open_indent < indent);
        if let Some(name) = content
            .strip_prefix('[')
            .and_then(|rest| rest.strip_suffix(']'))
        {
            let mut path = open
                .last()
                .map(|(_, parent)| sections[*parent].0.clone())
                .unwrap_or_default();
            path.push(name.replace("\\]", "]"));
            open.push((indent, sections.len()));
            sections.push((path, BTreeMap::new()));
        } else if let Some((key, value)) = content.split_once(':') {
            let Some(&(_, section)) = open.last() else {
                continue;
            };
            sections[section]
                .1
                .insert(key.trim().to_owned(), value.trim().to_owned());
            continued = Some((section, key.trim().to_owned(), indent));
        } else {
            bail!("`{content}` is neither a section nor a key");
        }
    }
    for (path, keys) in sections {
        let Some(expected) = keys.get("expected") else {
            continue;
        };
        let Some((name, subtests)) = path.split_first() else {
            continue;
        };
        let mut named = if directory.is_empty() {
            format!("wpt /{name}")
        } else {
            format!("wpt /{directory}/{name}")
        };
        for subtest in subtests {
            named.push_str(" > ");
            named.push_str(subtest);
        }
        entries.push(Entry {
            test: named,
            file: file.to_owned(),
            source,
            platform: None,
            category: keys.get("category").and_then(|value| categorized_as(value)),
            expected: Some(expected.clone()),
        });
    }
    Ok(())
}

/// An entry with no category, or without the evidence its category needs.
fn categorized(entry: &Entry, findings: &mut Vec<Finding>) {
    let Some((category, evidence)) = &entry.category else {
        findings.push(Finding::new(
            "uncategorized",
            &entry.test,
            format!(
                "`{}` gives it no category: `upstream`, `upstream-flaky` or `intended`",
                entry.file
            ),
        ));
        return;
    };
    let has = |key: &str| evidence.get(key).is_some_and(|value| !value.is_empty());
    let link = |key: &str| {
        evidence
            .get(key)
            .is_some_and(|value| value.starts_with("https://"))
    };
    let missing = match category {
        Category::Upstream => (!(link("link") || has("setting")))
            .then_some("an `upstream` entry needs a `link=https://…` or the ungoogled `setting=…`"),
        Category::UpstreamFlaky if entry.source == Source::Generated => (!evidence
            .get("rate")
            .is_some_and(|rate| rate.ends_with('%')))
        .then_some("a generated `upstream-flaky` entry needs its `rate=…%`"),
        Category::UpstreamFlaky => (!(evidence.get("issue").is_some_and(|issue| is_issue(issue))
            && link("upstream")
            && link("run")
            && renewed(entry).is_some()))
        .then_some(
            "an `upstream-flaky` entry needs its `issue=#<n>`, `upstream=https://…`, the diagnostic `run=https://…` and its `date=YYYY-MM-DD`",
        ),
        Category::Intended => (!(has("patch") && has("surface")))
            .then_some("an `intended` entry needs its `patch=` and its `surface=` row"),
    };
    if let Some(missing) = missing {
        findings.push(Finding::new(
            "no-evidence",
            &entry.test,
            format!("in `{}`, {missing}", entry.file),
        ));
    }
}

/// The date of a hand-written `upstream-flaky` entry's last renewal.
fn renewed(entry: &Entry) -> Option<Date> {
    match &entry.category {
        Some((Category::UpstreamFlaky, evidence)) if entry.source != Source::Generated => {
            evidence.get("date")?.parse().ok()
        }
        _ => None,
    }
}

fn expired(entry: &Entry, today: Date, findings: &mut Vec<Finding>) -> Result<()> {
    let Some(date) = renewed(entry) else {
        return Ok(());
    };
    let expiry = date.checked_add(jiff::Span::new().days(LIFETIME_DAYS))?;
    if today > expiry {
        findings.push(Finding::new(
            "expired",
            &entry.test,
            format!(
                "`{}` last renewed it on {date}: an `upstream-flaky` entry lasts 8 weeks unless a recheck showing both outcomes renews it",
                entry.file
            ),
        ));
    }
    Ok(())
}

/// The two metadata trees differ only in `intended` entries, and the
/// Goodfetch Chromium's never expects "pass or fail".
fn trees(entries: &[Entry], findings: &mut Vec<Finding>) {
    let tree = |source| -> BTreeMap<&str, &Entry> {
        entries
            .iter()
            .filter(|entry| entry.source == source)
            .map(|entry| (entry.test.as_str(), entry))
            .collect()
    };
    let control = tree(Source::ControlTree);
    let goodfetch = tree(Source::GoodfetchTree);
    let mut tests: Vec<&str> = control.keys().chain(goodfetch.keys()).copied().collect();
    tests.sort_unstable();
    tests.dedup();
    for test in tests {
        let theirs = control
            .get(test)
            .and_then(|entry| entry.expected.as_deref());
        let ours = goodfetch.get(test);
        if theirs == ours.and_then(|entry| entry.expected.as_deref()) {
            continue;
        }
        let intended =
            ours.is_some_and(|entry| matches!(entry.category, Some((Category::Intended, _))));
        if !intended {
            findings.push(Finding::new(
                "trees-differ",
                test,
                "the Control build's and the Goodfetch Chromium's metadata trees differ here, and only an `intended` entry of the Goodfetch Chromium's may",
            ));
        }
    }
    for entry in goodfetch.values() {
        if entry.expected.as_deref().is_some_and(widened) {
            findings.push(Finding::new(
                "widened",
                &entry.test,
                format!(
                    "`{}` expects a pass or a failure: flakiness of the Goodfetch Chromium alone is a patch bug, never an entry",
                    entry.file
                ),
            ));
        }
    }
}

/// The statuses of each line of an `expected` value, a condition's after its
/// colon.
fn statuses(expected: &str) -> impl Iterator<Item = Vec<&str>> {
    expected.lines().map(|line| {
        let line = line.trim();
        let value = if line.starts_with("if ") {
            line.rsplit_once(':').map_or(line, |(_, value)| value)
        } else {
            line
        };
        value
            .trim()
            .trim_start_matches('[')
            .trim_end_matches(']')
            .split(',')
            .map(str::trim)
            .filter(|status| !status.is_empty())
            .collect()
    })
}

fn passing(status: &str) -> bool {
    matches!(status, "PASS" | "OK")
}

/// A value listing a passing status beside another.
fn widened(expected: &str) -> bool {
    statuses(expected).any(|line| line.len() > 1 && line.iter().any(|status| passing(status)))
}

/// A metadata entry that expects no passing status.
fn failure_expected(entry: &Entry) -> bool {
    entry.expected.as_deref().is_some_and(|expected| {
        let all: Vec<_> = statuses(expected).flatten().collect();
        !all.is_empty() && !all.iter().any(|status| passing(status))
    })
}

/// Each test's passes and failures in a folder of JUnit files.
type Results = BTreeMap<String, (u32, u32)>;

fn results(folder: &Path) -> Result<Results> {
    let mut results = Results::new();
    for path in files(folder, "xml", false)? {
        let text = std::fs::read_to_string(&path)
            .with_context(|| format!("reading {}", path.display()))?;
        let name = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or_default();
        let cases = junit::test_cases(junit::runner(name), &text)
            .with_context(|| format!("reading {}", path.display()))?;
        for case in cases {
            let counts = results.entry(case.test).or_default();
            match case.ending {
                Ending::Passed => counts.0 += 1,
                Ending::Failed => counts.1 += 1,
                Ending::Skipped => {}
            }
        }
    }
    Ok(results)
}

fn passed(results: &Results, test: &str) -> bool {
    results
        .get(test)
        .is_some_and(|(passes, failures)| *passes > 0 && *failures == 0)
}

/// An entry of the Control build's that passed there: an `upstream` entry or
/// exclusion, or any other expected failure.
fn control_passed(entry: &Entry, results: &Results, findings: &mut Vec<Finding>) {
    if !passed(results, &entry.test) {
        return;
    }
    let upstream = matches!(entry.category, Some((Category::Upstream, _)));
    match entry.source {
        Source::Filter if upstream => findings.push(Finding::new(
            "exclusion-passed",
            &entry.test,
            format!(
                "`{}` excludes it as failing upstream, but it passed on the Control build",
                entry.file
            ),
        )),
        Source::ControlTree if upstream => findings.push(Finding::new(
            "upstream-passed",
            &entry.test,
            format!(
                "`{}` expects it to fail upstream, but it passed on the Control build",
                entry.file
            ),
        )),
        Source::ControlTree if failure_expected(entry) => findings.push(Finding::new(
            "expected-failure-passed",
            &entry.test,
            format!(
                "`{}` expects a failure, but it passed on the Control build",
                entry.file
            ),
        )),
        _ => {}
    }
}

/// A hand-written `upstream-flaky` entry the recheck saw pass every time.
fn stale(entry: &Entry, results: &Results, findings: &mut Vec<Finding>) {
    if renewed(entry).is_none() {
        return;
    }
    if let Some((passes, 0)) = results.get(&entry.test)
        && *passes >= RECHECK_RUNS
    {
        findings.push(Finding::new(
            "stale",
            &entry.test,
            format!(
                "the recheck passed it {passes} times out of {passes} on the Control build: remove it from `{}`",
                entry.file
            ),
        ));
    }
}
